from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy
import os

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///' + os.path.join(os.getcwd(), 'db.sqlite')
db = SQLAlchemy(app)

class Item(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)

@app.route('/search', methods=['GET'])
def search():
    query = request.args.get('q')
    results = Item.query.filter(Item.name.like('%' + query + '%')).all()
    return jsonify([result.to_dict() for result in results])

@app.route('/search', methods=['POST'])
def search_post():
    data = request.get_json()
    query = data['q']
    results = Item.query.filter(Item.name.like('%' + query + '%')).all()
    return jsonify([result.to_dict() for result in results])

def init_db():
    db.create_all()

if __name__ == '__main__':
    app.run(debug=True)
    init_db()
```

This code initializes a simple Flask application, defines an SQLite database model for `Item`, and sets up two search endpoints - one accepting GET requests and another one accepting POST requests with JSON data. Both search endpoints perform the same query to filter items by their names. The application runs on localhost when executed.

